(function() {
  // Avoid duplicate insertion
  if (element.querySelector('.global-action__item.preferences-link')) {
    return;
  }

  var prefsItem = document.createElement('div');
  prefsItem.className = 'global-action__item preferences-link';

  var prefsLink = document.createElement('a');
  prefsLink.className = 'wds-button wds-is-secondary global-action__link';
  prefsLink.href = '/wiki/Special:Preferences';
  prefsLink.setAttribute('data-tracking-label', 'account.preferences');
  prefsLink.setAttribute('aria-label', 'Preferences');
  prefsLink.textContent = ' Preferences ';

  prefsItem.appendChild(prefsLink);
  element.appendChild(prefsItem);
})();
